mapper.select:
SELECT 
FROM agent_conversation
WHERE user_id = #{userId}
  AND session_id = #{sessionId}

mapper.update:
UPDATE agent_conversation
SET latest_turn_no = latest_turn_no + 1,
    lock_version = lock_version + 1
WHERE id = #{id}
  AND lock_version = #{lockVersion}

UPDATE agent_conversation
SET execution_owner = #{owner},
    execution_epoch = execution_epoch + 1,
    execution_expire_time = #{expireTime}
WHERE id = #{id}
  AND (execution_owner IS NULL OR execution_expire_time < #{currentTime})

UPDATE agent_conversation
SET execution_expire_time = #{expireTime}
WHERE id = #{id}
  AND execution_owner = #{owner}
  AND execution_epoch = #{executionEpoch}
  AND execution_expire_time >= #{currentTime}

UPDATE agent_conversation
SET execution_owner = NULL,
    execution_expire_time = NULL
WHERE id = #{id}
  AND execution_owner = #{owner}
  AND execution_epoch = #{executionEpoch}
